CREATE TABLE IF NOT EXISTS pcc_products (sku TEXT PRIMARY KEY, name TEXT NOT NULL, family TEXT NOT NULL, unit TEXT, length INTEGER, base_cents INTEGER, currency TEXT, price_confirmed INTEGER NOT NULL DEFAULT 0, source_at INTEGER, source TEXT NOT NULL, technical TEXT NOT NULL DEFAULT '{}', updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_listings (id TEXT PRIMARY KEY, sku TEXT, title TEXT NOT NULL, status TEXT, price_cents INTEGER, currency TEXT, category_id TEXT, listing_type_id TEXT, source TEXT NOT NULL, source_at INTEGER, payload TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS pcc_listing_sku ON pcc_listings(sku);
CREATE TABLE IF NOT EXISTS pcc_imports (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, status TEXT NOT NULL, summary TEXT NOT NULL, created INTEGER NOT NULL, applied INTEGER);
CREATE TABLE IF NOT EXISTS pcc_import_rows (batch TEXT NOT NULL, kind TEXT NOT NULL, row_key TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(batch, kind, row_key));
CREATE TABLE IF NOT EXISTS pcc_drafts (id TEXT PRIMARY KEY, sku TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, validation TEXT, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_questions (id TEXT PRIMARY KEY, item_id TEXT NOT NULL, text TEXT NOT NULL, status TEXT NOT NULL, answer TEXT, draft TEXT, source_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_settings (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_mfa (id INTEGER PRIMARY KEY CHECK(id=1), secret TEXT, pending TEXT, last_counter INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pcc_mfa_sessions (hash TEXT PRIMARY KEY, admin_hash TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_mfa_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, attempts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, target TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, result TEXT, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, due INTEGER NOT NULL, lease INTEGER, error TEXT, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_audit (id TEXT PRIMARY KEY, action TEXT NOT NULL, target TEXT NOT NULL, result TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_quotes (id TEXT PRIMARY KEY, payload TEXT NOT NULL, result TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pcc_sources (id TEXT PRIMARY KEY, status TEXT NOT NULL, last_attempt INTEGER, last_success INTEGER, detail TEXT);
CREATE TABLE IF NOT EXISTS pcc_metrics (id TEXT PRIMARY KEY, day TEXT NOT NULL, kind TEXT NOT NULL, value TEXT NOT NULL, source_at INTEGER NOT NULL);
